begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('95000000-0000-0000-0000-000000000001','workflow@example.test');
update public.profiles set active=true,role='DISPATCHER' where id='95000000-0000-0000-0000-000000000001';
select set_config('test.request',(select id::text from public.moving_requests where request_number='LM-001001'),true);
select set_config('test.mile',(select id::text from public.moving_requests where request_number='LM-001002'),true);
select is(private.quote_total('LOCAL',2,11900,3),35700::bigint,'Local minimum parity');
select is(private.quote_total('LOCAL',3+40::numeric/60,11900,3),47600::bigint,'Fractional hours parity');
select is(private.quote_total('LOCAL',5,14500,3),72500::bigint,'Three mover rate not multiplied again');
select is(private.quote_total('PER_MILE',125.4,400,3),50400::bigint,'Fractional miles parity');
select is(private.quote_total('PER_MILE',0.1,400,3),400::bigint,'No mileage minimum');
select throws_ok($$select private.quote_total('PER_MILE','NaN',400,3)$$,'P0001','INVALID_INPUT','NaN rejected');
select throws_ok($$select private.quote_total('LOCAL',169,11900,3)$$,'P0001','INVALID_INPUT','Excessive duration rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','95000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.save_quote(current_setting('test.request')::uuid,0,'LOCAL',2,11900,3)$$,'Dispatcher creates quote');
select is((select estimated_total_cents from public.quotes where request_id=current_setting('test.request')::uuid),35700::bigint,'Server computes estimate');
select throws_ok($$select public.save_quote(current_setting('test.request')::uuid,0,'LOCAL',2,11900,3)$$,'P0001','CONFLICT','Stale create fails');
select throws_ok($$select public.communicate_quote(current_setting('test.request')::uuid,1,'PHONE',now(),'yes',true)$$,'P0001','INVALID_TRANSITION','Unapproved terms cannot be confirmed');
select lives_ok($$select public.approve_quote(current_setting('test.request')::uuid,1)$$,'Dispatcher approves');
select lives_ok($$select public.communicate_quote(current_setting('test.request')::uuid,2,'PHONE',now(),'Waiting',false)$$,'Manual communication recorded');
select is((select status from public.quotes where request_id=current_setting('test.request')::uuid),'ACCEPTED','Communication alone does not confirm');
select lives_ok($$select public.communicate_quote(current_setting('test.request')::uuid,3,'WHATSAPP',now(),'Customer accepts rate and minimum',true)$$,'Acceptance confirms terms');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'CONFIRMED','Request confirmed atomically');
select lives_ok($$select public.schedule_move(current_setting('test.request')::uuid,0,date_trunc('week',now())+interval '8 days 14 hours','Fixture',180)$$,'Confirmed request schedules');
select lives_ok($$select public.schedule_move(current_setting('test.request')::uuid,0,date_trunc('week',now())+interval '8 days 14 hours','Retry',180)$$,'Repeated conversion reuses move');
select is((select count(*)::integer from public.moves where request_id=current_setting('test.request')::uuid),1,'Only one move');
select throws_ok($$select public.schedule_move(current_setting('test.request')::uuid,1,date_trunc('week',now() at time zone 'America/New_York') at time zone 'America/New_York'+interval '13 days 12 hours','',180)$$,'P0001','INVALID_INPUT','Sunday scheduling rejected');
select lives_ok($$select public.save_quote(current_setting('test.request')::uuid,4,'LOCAL',2,12000,3)$$,'Rate change invalidates terms');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,1,'start',now()-interval '4 hours',null,null)$$,'P0001','INVALID_TRANSITION','Unconfirmed revised rate blocks start');
select lives_ok($$select public.approve_quote(current_setting('test.request')::uuid,5)$$,'Revised quote approved');
select lives_ok($$select public.communicate_quote(current_setting('test.request')::uuid,6,'PHONE',now(),'Agreed revised terms',true)$$,'Reconfirmation');
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,1,'start',now()-interval '4 hours',null,null)$$,'Start synchronizes operation');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,2,'complete',now(),now()-interval '1 hour',null)$$,'P0001','INVALID_INPUT','Reversed times rejected');
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,2,'complete',now()-interval '4 hours',now(),null)$$,'Dispatcher completes');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),48000::bigint,'Actual total calculated');
select is((select estimated_total_cents from public.quotes where request_id=current_setting('test.request')::uuid),36000::bigint,'Estimate preserved separately');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,3,'correct',now()-interval '5 hours',now(),null)$$,'42501',null,'Dispatcher cannot correct closed move');
select throws_ok($$select public.save_quote(current_setting('test.request')::uuid,7,'LOCAL',2,13000,3)$$,'42501',null,'Dispatcher cannot edit closed rate');
reset role;
update public.profiles set role='MANAGER' where id='95000000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$select public.save_quote(current_setting('test.request')::uuid,7,'LOCAL',2,13000,3)$$,'Manager revises closed rate');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),48000::bigint,'Previous confirmed total preserved');
select is((select revised_total_cents from public.moves where request_id=current_setting('test.request')::uuid),52000::bigint,'Revised amount pending acceptance');
select lives_ok($$select public.approve_quote(current_setting('test.request')::uuid,8)$$,'Manager approves revision');
select lives_ok($$select public.communicate_quote(current_setting('test.request')::uuid,9,'EMAIL',now(),'Customer accepts revised rate',true)$$,'Customer accepts revision');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'COMPLETED','Confirmation never reopens completed work');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),52000::bigint,'Accepted revision becomes final total');
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,(select version from public.moves where request_id=current_setting('test.request')::uuid),'correct',now()-interval '5 hours',now(),null)$$,'Manager corrects actual time');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),65000::bigint,'Time correction recalculates without rate reconfirmation');
select ok(exists(select 1 from public.pricing_change_history where request_id=current_setting('test.request')::uuid and field='started_at' and old_value is not null),'Actual time history preserved');
select lives_ok($$select public.save_quote(current_setting('test.mile')::uuid,0,'PER_MILE',4,400,100)$$,'Mileage quote');
select lives_ok($$select public.approve_quote(current_setting('test.mile')::uuid,1)$$,'Mileage approval');
select lives_ok($$select public.communicate_quote(current_setting('test.mile')::uuid,2,'PHONE',now(),'Agreed',true)$$,'Mileage confirmation');
select lives_ok($$select public.schedule_move(current_setting('test.mile')::uuid,0,date_trunc('week',now())+interval '8 days 14 hours','',180)$$,'Overlapping booking allowed');
select lives_ok($$select public.record_move(current_setting('test.mile')::uuid,1,'start',now()-interval '4 hours',null,null)$$,'Mileage start');
select lives_ok($$select public.record_move(current_setting('test.mile')::uuid,2,'complete',now()-interval '4 hours',now(),110.2)$$,'Mileage close');
select is((select final_total_cents from public.moves where request_id=current_setting('test.mile')::uuid),44400::bigint,'Mileage amount parity');
select set_config('test.reactivate',(select id::text from public.moving_requests where request_number='LM-001004'),true);
select set_config('test.original_move',(select id::text from public.moves where request_id=current_setting('test.reactivate')::uuid),true);
select lives_ok($$select public.request_action(current_setting('test.reactivate')::uuid,(select version from public.moving_requests where id=current_setting('test.reactivate')::uuid),'cancel','')$$,'Cancel scheduled move');
select lives_ok($$select public.request_action(current_setting('test.reactivate')::uuid,(select version from public.moving_requests where id=current_setting('test.reactivate')::uuid),'reactivate','')$$,'Reactivate for review');
select throws_ok($$select public.schedule_move(current_setting('test.reactivate')::uuid,(select version from public.moves where request_id=current_setting('test.reactivate')::uuid),date_trunc('week',now())+interval '8 days 14 hours','',180)$$,'P0001','INVALID_TRANSITION','Reactivation cannot skip quote review');
select lives_ok($$select public.approve_quote(current_setting('test.reactivate')::uuid,(select version from public.quotes where request_id=current_setting('test.reactivate')::uuid))$$,'Review cancelled terms');
select lives_ok($$select public.communicate_quote(current_setting('test.reactivate')::uuid,(select version from public.quotes where request_id=current_setting('test.reactivate')::uuid),'PHONE',now(),'Reviewed and accepted',true)$$,'Reconfirm after reactivation');
select lives_ok($$select public.schedule_move(current_setting('test.reactivate')::uuid,(select version from public.moves where request_id=current_setting('test.reactivate')::uuid),date_trunc('week',now())+interval '8 days 14 hours','',180)$$,'Reschedule reviewed move');
select is((select id::text from public.moves where request_id=current_setting('test.reactivate')::uuid),current_setting('test.original_move'),'Same move reused after review');
select is((select status from public.moves where request_id=current_setting('test.reactivate')::uuid),'SCHEDULED','Reviewed move scheduled');
reset role;
select * from finish();
rollback;
